import os
if os.path.exists("kas.txt"):
    os.remove("kas.txt")

def catat(baris):
    with open("kas.txt", "a") as f:
        f.write(baris + "\n")

def saldo():
    total = 0
    with open("kas.txt") as f:
        for b in f:
            jenis, jumlah, ket = b.strip().split(";", 2)
            if jenis == "masuk":
                total += int(jumlah)
            else:
                total -= int(jumlah)
    return total

for _ in range(int(input())):
    catat(input())
print("Saldo:", saldo())

